import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
  JxDivider,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUS_FILTERS: Array<{ value: ProjectStatus; label: string }> = [
  { value: 'active', label: 'Активные' },
  { value: 'paused', label: 'На паузе' },
  { value: 'over', label: 'Превышение' },
];

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекст-лаборатория', used: 720, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Импорт аналитики', used: 240, quota: 1000, status: 'paused' },
  { id: 'p3', name: 'Витрина отчётов', used: 1180, quota: 1000, status: 'over' },
  { id: 'p4', name: 'Мобильный клиент', used: 455, quota: 1000, status: 'active' },
  { id: 'p5', name: 'Поисковый индекс', used: 890, quota: 1000, status: 'active' },
  { id: 'p6', name: 'Очередь уведомлений', used: 130, quota: 1000, status: 'paused' },
  { id: 'p7', name: 'Биллинг и лимиты', used: 1020, quota: 1000, status: 'over' },
  { id: 'p8', name: 'Экспорт в хранилище', used: 610, quota: 1000, status: 'active' },
  { id: 'p9', name: 'Документация портала', used: 95, quota: 1000, status: 'paused' },
  { id: 'p10', name: 'Служба авторизации', used: 780, quota: 1000, status: 'active' },
  { id: 'p11', name: 'Пайплайн сборки', used: 340, quota: 1000, status: 'active' },
  { id: 'p12', name: 'Архив логов', used: 1340, quota: 1000, status: 'over' },
];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(['active', 'paused', 'over']);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((prev) => prev.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUS_FILTERS.map((filter) => filter.value));
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты за текущий период: {filtered.length} из {PROJECTS.length} проектов.
        </p>
      </header>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {STATUS_FILTERS.filter((filter) => statuses.includes(filter.value)).map((filter) => (
          <JxChip
            key={filter.value}
            active
            removable
            onRemove={() => removeStatus(filter.value)}
          >
            {filter.label}
          </JxChip>
        ))}
        {statuses.length < STATUS_FILTERS.length && (
          <JxButton variant="ghost" size="sm" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        )}
      </div>

      <JxDivider />

      {visible.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Сняты все статусы, поэтому список пуст. Верните фильтры, чтобы снова увидеть проекты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => {
              const meta = STATUS_META[project.status];
              const percent = Math.round((project.used / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 14px',
                    background: 'var(--jx-surface-2)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <JxProgressCircle
                    value={Math.min(percent, 100)}
                    showValue
                    aria-label={`Квота проекта «${project.name}» заполнена на ${percent} процентов`}
                  />
                  <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: '2px' }}>
                    <span
                      style={{
                        fontSize: '15px',
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </span>
                    <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>
                      {project.used} из {project.quota} единиц — {percent}%
                    </span>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

